// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Вход по нику и паролю
	// (POST /api/v1/auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Завершить текущий сеанс
	// (POST /api/v1/auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Завершить все сеансы
	// (POST /api/v1/auth/logout-all)
	LogoutAll(ctx context.Context, request LogoutAllRequestObject) (LogoutAllResponseObject, error)
	// Регистрация
	// (POST /api/v1/auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// Вход через Telegram Login Widget
	// (POST /api/v1/auth/telegram)
	LoginTelegram(ctx context.Context, request LoginTelegramRequestObject) (LoginTelegramResponseObject, error)
	// Окончательно удалить кабель
	// (DELETE /api/v1/cables/{cableId})
	DeleteCable(ctx context.Context, request DeleteCableRequestObject) (DeleteCableResponseObject, error)
	// Кабель
	// (GET /api/v1/cables/{cableId})
	GetCable(ctx context.Context, request GetCableRequestObject) (GetCableResponseObject, error)
	// Изменить атрибуты кабеля
	// (PUT /api/v1/cables/{cableId})
	UpdateCable(ctx context.Context, request UpdateCableRequestObject) (UpdateCableResponseObject, error)
	// Отправить кабель в архив
	// (POST /api/v1/cables/{cableId}/archive)
	ArchiveCable(ctx context.Context, request ArchiveCableRequestObject) (ArchiveCableResponseObject, error)
	// История тестов кабеля
	// (GET /api/v1/cables/{cableId}/tests)
	ListCableTests(ctx context.Context, request ListCableTestsRequestObject) (ListCableTestsResponseObject, error)
	// Вернуть кабель из архива
	// (POST /api/v1/cables/{cableId}/unarchive)
	UnarchiveCable(ctx context.Context, request UnarchiveCableRequestObject) (UnarchiveCableResponseObject, error)
	// Удаление учётной записи
	// (DELETE /api/v1/me)
	DeleteMe(ctx context.Context, request DeleteMeRequestObject) (DeleteMeResponseObject, error)
	// Профиль текущего пользователя
	// (GET /api/v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// Смена ника
	// (PATCH /api/v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Смена пароля
	// (PUT /api/v1/me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// Отвязка Telegram
	// (DELETE /api/v1/me/telegram)
	UnlinkTelegram(ctx context.Context, request UnlinkTelegramRequestObject) (UnlinkTelegramResponseObject, error)
	// Привязка Telegram
	// (PUT /api/v1/me/telegram)
	LinkTelegram(ctx context.Context, request LinkTelegramRequestObject) (LinkTelegramResponseObject, error)
	// Мои команды
	// (GET /api/v1/teams)
	ListTeams(ctx context.Context, request ListTeamsRequestObject) (ListTeamsResponseObject, error)
	// Создать команду
	// (POST /api/v1/teams)
	CreateTeam(ctx context.Context, request CreateTeamRequestObject) (CreateTeamResponseObject, error)
	// Удалить команду
	// (DELETE /api/v1/teams/{teamId})
	DeleteTeam(ctx context.Context, request DeleteTeamRequestObject) (DeleteTeamResponseObject, error)
	// Команда
	// (GET /api/v1/teams/{teamId})
	GetTeam(ctx context.Context, request GetTeamRequestObject) (GetTeamResponseObject, error)
	// Название и описание команды
	// (PATCH /api/v1/teams/{teamId})
	UpdateTeam(ctx context.Context, request UpdateTeamRequestObject) (UpdateTeamResponseObject, error)
	// Каталог кабелей команды
	// (GET /api/v1/teams/{teamId}/cables)
	ListCables(ctx context.Context, request ListCablesRequestObject) (ListCablesResponseObject, error)
	// Выйти из команды
	// (POST /api/v1/teams/{teamId}/leave)
	LeaveTeam(ctx context.Context, request LeaveTeamRequestObject) (LeaveTeamResponseObject, error)
	// Участники команды
	// (GET /api/v1/teams/{teamId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// Исключить участника
	// (DELETE /api/v1/teams/{teamId}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// Восстановить удалённую команду
	// (POST /api/v1/teams/{teamId}/restore)
	RestoreTeam(ctx context.Context, request RestoreTeamRequestObject) (RestoreTeamResponseObject, error)
	// Передать владение
	// (POST /api/v1/teams/{teamId}/transfer-ownership)
	TransferOwnership(ctx context.Context, request TransferOwnershipRequestObject) (TransferOwnershipResponseObject, error)
	// Тест
	// (GET /api/v1/tests/{testId})
	GetTest(ctx context.Context, request GetTestRequestObject) (GetTestResponseObject, error)
	// Снять пометку «недействительный»
	// (DELETE /api/v1/tests/{testId}/invalidation)
	RevalidateTest(ctx context.Context, request RevalidateTestRequestObject) (RevalidateTestResponseObject, error)
	// Пометить тест недействительным
	// (PUT /api/v1/tests/{testId}/invalidation)
	InvalidateTest(ctx context.Context, request InvalidateTestRequestObject) (InvalidateTestResponseObject, error)
	// Проверка сервера и БД
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
}

type StrictHandlerFunc = strictgin.StrictGinHandlerFunc
type StrictMiddlewareFunc = strictgin.StrictGinMiddlewareFunc

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares}
}

